  ((( &( "inf" ) )) # Int  |->_)
  **  ((( &( "width" ) )) # Int  |-> n_pre)
  **  ((( &( "pos" ) )) # Ptr  |-> pos_pre)
  **  ((( &( "power" ) )) # Ptr  |-> power_pre)
  **  ((( &( "n" ) )) # Int  |-> n_pre)
  **  ((( &( "c" ) )) # Int  |-> c_pre)
  **  ((( &( "pre" ) )) # Ptr  |-> pre_pre)
  **  ((( &( "dp_l" ) )) # Ptr  |-> dp_l_pre)
  **  ((( &( "dp_r" ) )) # Ptr  |-> dp_r_pre)
